const $=selector=>document.querySelector(selector);
const money=value=>new Intl.NumberFormat('ru-RU').format(value)+' ₽';
const dishes=[
['salmon','Лосось','Нежный лосось, рис, васаби','nigiri',490,'90 г · 2 шт.','Чистая классика','Рыба, соя'],
['tuna','Тунец','Тунец аками, рис, васаби','nigiri',590,'90 г · 2 шт.','','Рыба, соя'],
['shrimp','Креветка','Тигровая креветка, рис, васаби','nigiri',490,'80 г · 2 шт.','','Ракообразные, соя'],
['eel','Угорь унаги','Угорь, соус унаги, рис, нори','nigiri',690,'90 г · 2 шт.','Умами','Рыба, соя, пшеница'],
['scallop','Гребешок юдзу','Морской гребешок, рис, юдзу','nigiri',790,'90 г · 2 шт.','','Моллюски, соя'],
['ikura','Икра. Море внутри','Икра лосося, рис, хрустящие нори','gunkan',690,'80 г · 2 шт.','','Рыба, соя'],
['philadelphia','Филадельфия суприм','Лосось, сливочный сыр, авокадо','roll',990,'280 г · 8 шт.','Ваш любимый','Рыба, молоко, соя'],
['dragon','Зелёный дракон','Угорь, авокадо, кунжут, унаги','roll',1190,'290 г · 8 шт.','','Рыба, кунжут, соя, пшеница'],
['tempura','Креветка темпура','Креветка, авокадо, хрустящая темпура','roll',890,'270 г · 8 шт.','Тёплый характер','Ракообразные, пшеница, яйца, соя'],
['spicy-tuna','Спайси тунец','Тунец, соус спайси, рис, кунжут','roll',990,'260 г · 8 шт.','С огоньком','Рыба, кунжут, яйца, соя']
].map((d,id)=>({id,slug:d[0],name:d[1],description:d[2],category:d[3],price:d[4],weight:d[5],tag:d[6],allergens:d[7],image:'assets/'+d[0]+'.png'}));
let cart={},favorites=[],category='all',query='',favoritesOnly=false,guests=2,cutlery=true,route='home',surpriseIndex=0;
try{const saved=JSON.parse(localStorage.getItem('yaki-supreme-v2')||'{}');cart=Object.fromEntries(Object.entries(saved.cart||{}).filter(([id,quantity])=>dishes[id]&&Number.isInteger(quantity)&&quantity>0&&quantity<100));favorites=(saved.favorites||[]).filter(id=>Number.isInteger(id)&&dishes[id])}catch{}
function total(){return Object.entries(cart).reduce((sum,[id,n])=>sum+dishes[id].price*n,0)}
function count(){return Object.values(cart).reduce((sum,n)=>sum+n,0)}
let catalogInView=false;
function persist(){try{localStorage.setItem('yaki-supreme-v2',JSON.stringify({cart,favorites}))}catch{}const n=count();$('#bagCount').textContent=n;$('#mobileCount').textContent=n;$('#floatingCount').textContent=n;$('#floatingTotal').textContent=money(total());$('#floatingBag').hidden=!n||route==='order'||!catalogInView}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.yakiToast);window.yakiToast=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function quantityControl(id){return cart[id]?`<div class="card-quantity"><button data-change="${id}" data-delta="-1" aria-label="Убрать одну порцию ${dishes[id].name}">−</button><span>${cart[id]}</span><button data-change="${id}" data-delta="1" aria-label="Добавить порцию ${dishes[id].name}">+</button></div>`:`<button class="add-button" data-add="${id}" aria-label="Добавить ${dishes[id].name}">+</button>`}
function renderCatalog(){const list=dishes.filter(d=>(category==='all'||d.category===category)&&(!favoritesOnly||favorites.includes(d.id))&&(!query||(d.name+' '+d.description).toLowerCase().includes(query)));$('#productGrid').innerHTML=list.map(d=>`<article class="product" style="animation-delay:${d.id*.025}s"><div class="product-art palette-${d.id}"><button class="art-open" data-detail="${d.id}" aria-label="Подробнее: ${d.name}"><img src="${d.image}" alt="${d.name}" loading="${d.id<4?'eager':'lazy'}" width="512" height="512"></button>${d.tag?`<span class="product-tag">${d.tag}</span>`:''}<button class="favorite" data-favorite="${d.id}" aria-label="Избранное: ${d.name}" aria-pressed="${favorites.includes(d.id)}">${favorites.includes(d.id)?'♥':'♡'}</button></div><div class="product-caption"><h3><button data-detail="${d.id}">${d.name}</button></h3><p>${d.description}</p><div class="product-bottom"><div><strong>${money(d.price)}</strong><small>${d.weight}</small></div><div class="quantity-slot" data-slot="${d.id}">${quantityControl(d.id)}</div></div></div></article>`).join('')||`<div class="no-results">${favoritesOnly?'Здесь будут ваши любимые вкусы. Нажмите ♡ на карточке.':'Такого вкуса пока нет. Попробуйте другой запрос.'}<button id="resetFilters">Показать всё меню</button></div>`;if($('#resetFilters'))$('#resetFilters').onclick=resetFilters}
function resetFilters(){category='all';query='';favoritesOnly=false;$('#searchInput').value='';$('#favoritesToggle').setAttribute('aria-pressed','false');document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('selected',b.dataset.category==='all');b.setAttribute('aria-pressed',b.dataset.category==='all')});renderCatalog()}
function changeQuantity(id,delta){const next=(cart[id]||0)+delta;if(next>99){toast('Можно добавить до 99 порций');return}if(next>0)cart[id]=next;else delete cart[id];persist();document.querySelectorAll(`[data-slot="${id}"]`).forEach(slot=>slot.innerHTML=quantityControl(id));if(route==='order')renderOrder(false)}
document.addEventListener('click',event=>{const add=event.target.closest('[data-add]'),change=event.target.closest('[data-change]'),favorite=event.target.closest('[data-favorite]'),detail=event.target.closest('[data-detail]');if(add){changeQuantity(+add.dataset.add,1);toast(dishes[+add.dataset.add].name+' — в вашем заказе')}if(change)changeQuantity(+change.dataset.change,+change.dataset.delta);if(favorite){const id=+favorite.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(v=>v!==id):[...favorites,id];persist();renderCatalog()}if(detail)showProduct(+detail.dataset.detail)});
document.querySelectorAll('[data-category]').forEach(button=>button.onclick=()=>{category=button.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',b===button)});renderCatalog()});$('#favoritesToggle').onclick=()=>{favoritesOnly=!favoritesOnly;$('#favoritesToggle').setAttribute('aria-pressed',favoritesOnly);renderCatalog()};$('#searchInput').oninput=e=>{query=e.target.value.trim().toLowerCase();renderCatalog()};
function showProduct(id){const d=dishes[id];$('#productDetail').innerHTML=`<div class="detail-layout"><div class="detail-art palette-${id}"><img src="${d.image}" alt="${d.name}"></div><div class="detail-copy"><div class="eyebrow">ЯКИ СУПРИМ / ${d.category==='roll'?'РОЛЛЫ':d.category==='gunkan'?'ГУНКАНЫ':'НИГИРИ'}</div><h2>${d.name}</h2><p>${d.description}.</p><small>${d.weight} · готовим под ваш заказ</small><button class="pill pill-dark" id="detailAdd">Добавить <b>${money(d.price)}</b> </button><p class="allergen">Аллергены: ${d.allergens}. Если есть ограничения, состав нужно уточнить перед реальным заказом.</p></div></div>`;$('#productDialog').showModal();$('#detailAdd').onclick=()=>{changeQuantity(id,1);$('#productDialog').close();toast(d.name+' — в вашем заказе')}}
$('#surpriseButton').onclick=()=>{const candidates=dishes.filter(d=>!cart[d.id]);const pick=(candidates.length?candidates:dishes)[surpriseIndex++%(candidates.length||dishes.length)];showProduct(pick.id)};
let orderDraft={};function readDraft(){const form=$('#orderForm');if(form)orderDraft=Object.fromEntries(new FormData(form))}
function renderOrder(preserve=true){if(preserve)readDraft();const ids=Object.keys(cart);if(!ids.length){$('#orderBody').innerHTML='<div class="empty-order"><div class="empty-symbol">◌</div><h2>Место для любимого вкуса.</h2><p>Пока здесь ничего нет. Давайте это исправим.</p><a class="pill pill-dark" href="#catalog">Открыть меню </a></div>';return}const hero=dishes[ids.find(id=>dishes[id].category==='roll')||ids[0]];
$('#orderBody').innerHTML=`<div class="order-layout"><div class="order-moment"><div class="order-aura"></div><div class="eyebrow">СОБРАНО ПО ВАШЕМУ НАСТРОЕНИЮ</div><h2>Кажется, вечер<br>будет прекрасным.</h2><img class="order-hero-image" src="${hero.image}" alt="${hero.name}"><span class="order-hero-name">${hero.name}</span><div class="ritual-controls"><div class="glass-row"><span>Разделим момент?<br><small>Количество персон</small></span><div class="counter"><button id="guestsMinus" aria-label="Уменьшить число персон" ${guests<=1?'disabled':''}>−</button><span id="guestsNumber">${guests}</span><button id="guestsPlus" aria-label="Увеличить число персон" ${guests>=12?'disabled':''}>+</button></div></div><div class="glass-row"><span>Палочки и салфетки<br><small>Бережём то, что важно</small></span><button id="cutleryToggle" role="switch" aria-checked="${cutlery}" aria-label="Добавить приборы">${cutlery?'✓':'＋'}</button></div></div></div><div class="order-panel"><h2>Ваш заказ <span style="color:#a1a9ad">/ ${count()}</span></h2><p class="order-caption">Именно то, чего хотелось.</p><div id="orderItems">${ids.map(id=>{const d=dishes[id];return `<article class="order-item"><img src="${d.image}" alt=""><div><h3>${d.name}</h3><p>${d.weight}</p></div><div><strong>${money(d.price*cart[id])}</strong><div class="item-counter"><button data-change="${id}" data-delta="-1" aria-label="Убрать порцию ${d.name}">−</button><span>${cart[id]}</span><button data-change="${id}" data-delta="1" aria-label="Добавить порцию ${d.name}">+</button></div></div></article>`}).join('')}</div><div class="order-summary"><span>Итого</span><strong>${money(total())}</strong></div><form id="orderForm" class="order-form"><label class="field">Ваше имя<input name="name" autocomplete="given-name" placeholder="Как к вам обращаться" maxlength="80" required></label><label class="field">Телефон<input name="phone" type="tel" autocomplete="tel" placeholder="+7 (999) 123-45-67" pattern="[+0-9 ()-]{10,20}" required></label><label class="field field-wide">Адрес доставки<input name="address" autocomplete="street-address" placeholder="Город, улица, дом, квартира" maxlength="200" required></label><label class="field field-wide">Комментарий<input name="comment" placeholder="Что сделает ваш вечер ещё лучше?" maxlength="300"></label><button class="pill pill-dark" type="submit">Завершить демозаказ </button></form><p class="demo-note">Это концепт доставки. Заказ демонстрационный: данные никуда не отправляются, оплата не взимается. Изображения блюд созданы специально для этого меню.</p></div></div>`;
for(const [name,value] of Object.entries(orderDraft)){const el=$('#orderForm').elements.namedItem(name);if(el)el.value=value}
$('#orderForm').oninput=readDraft;$('#orderForm').onsubmit=e=>{e.preventDefault();readDraft();cart={};orderDraft={};persist();renderOrder(false);showInfo('<div class="eyebrow">АРИГАТО / ありがとう</div><h2>Прекрасный момент.</h2><p>Ваш демонстрационный заказ собран. Никаких списаний, звонков или отправки данных — только знакомство с Яки Суприм.</p><button class="pill pill-dark" id="successHome">На главную </button>');$('#successHome').onclick=()=>{$('#infoDialog').close();location.hash='home'}};
$('#guestsMinus').onclick=()=>{guests=Math.max(1,guests-1);renderOrder()};$('#guestsPlus').onclick=()=>{guests=Math.min(12,guests+1);renderOrder()};$('#cutleryToggle').onclick=()=>{cutlery=!cutlery;$('#cutleryToggle').setAttribute('aria-checked',cutlery);$('#cutleryToggle').textContent=cutlery?'✓':'＋'};
}
function navigate(){readDraft();route=['home','catalog','order'].includes(location.hash.slice(1))?location.hash.slice(1):'home';$('#homeView').hidden=route==='order';$('#catalogView').hidden=route==='order';$('#orderView').hidden=route!=='order';document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===route);if(a.dataset.route===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(route!=='order')renderCatalog();else renderOrder(false);persist();document.title=`${route==='home'?'Почувствуй вкус момента':route==='catalog'?'Меню':'Ваш заказ'} — Яки Суприм`;requestAnimationFrame(()=>{if(route==='catalog')$('#catalogView').scrollIntoView({behavior:'instant',block:'start'});else window.scrollTo({top:0,behavior:'instant'})})}
$('#bagOpen').onclick=$('#floatingOpen').onclick=()=>{location.hash='order'};addEventListener('hashchange',navigate);document.addEventListener('click',event=>{const link=event.target.closest('a[href="#home"],a[href="#catalog"]');if(link&&link.hash===location.hash){event.preventDefault();navigate()}});
function showInfo(html){$('#infoContent').innerHTML=html;$('#infoDialog').showModal()}
$('#aboutOpen').onclick=()=>showInfo('<div class="eyebrow">ЯПОНСКАЯ КУХНЯ. НОВОЕ НАСТРОЕНИЕ.</div><h2>Яки Суприм.</h2><p>Мы придумали место, где выбор еды начинается с ощущения. Яркие вкусы, немного любопытства и удовольствие от простых вещей.</p><p>В этом концепте всё посвящено моменту: от тихой воды на первом экране до цвета вашего любимого ролла.</p><a class="pill pill-dark" id="aboutMenu" href="#catalog">Почувствовать вкус </a>');$('#infoDialog').addEventListener('click',e=>{if(e.target.closest('#aboutMenu'))$('#infoDialog').close()});$('#deliveryOpen').onclick=()=>showInfo('<div class="eyebrow">ВНИМАНИЕ К ДЕТАЛЯМ</div><h2>Ближе к вашему вечеру.</h2><p>Этот сайт — концепт премиальной доставки. Реальные зоны, часы работы, стоимость доставки и приём платежей пока не подключены.</p><p>Вы можете изучить десять блюд, сохранить любимые и пройти весь демонстрационный сценарий заказа.</p>');
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})});
let audio,waterSource;$('#soundToggle').onclick=async()=>{try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();const buffer=audio.createBuffer(1,audio.sampleRate*4,audio.sampleRate);const values=buffer.getChannelData(0);let sample=0;for(let i=0;i<values.length;i++){sample=(sample+(Math.random()-.5)*.035)*.992;values[i]=sample}waterSource=audio.createBufferSource();waterSource.buffer=buffer;waterSource.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=600;const gain=audio.createGain();gain.gain.value=.18;waterSource.connect(filter).connect(gain).connect(audio.destination);waterSource.start()}const on=$('#soundToggle').getAttribute('aria-pressed')!=='true';await(on?audio.resume():audio.suspend());$('#soundToggle').setAttribute('aria-pressed',on);$('#soundToggle').setAttribute('aria-label',on?'Выключить звук воды':'Включить звук воды')}catch{toast('Браузер не смог включить звук')}};
new IntersectionObserver(entries=>{catalogInView=entries[0].isIntersecting;persist()},{threshold:0}).observe($('#catalogView'));
navigate();
